insert into public.markets (id, workspace_id, name, location, strategy, criteria, asset_class, decision, decision_why, decision_next_step, last_scored_at, created_by, created_at, updated_at) values
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Knoxville', 'Knoxville, TN', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Solid Foundation-level growth and low taxes, but a real conflict between an older data point (positive rent growth) and a fresh Q1 2026 report (rents down, price-per-unit softening) plus tight affordability at 30.8%.', 'Get a broker to confirm which rent-growth read is current before underwriting; recheck once the stadium/business-park hiring shows up in absorption data.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Huntsville', 'Huntsville, AL', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'go', 'Best cost structure and rent growth of the TN/AL group, with the one real flag being Redstone Arsenal concentration and a thinner institutional exit pool given the smaller metro size.', 'Comfortable as a primary market if you''re okay underwriting around defense-budget exposure; otherwise treat the employer row as a standing watch item.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('92e86150-e5be-4e5c-a72e-51e011fd3ef4', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Clarksville', 'Clarksville, TN', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'Clean, low-cost, low-crime market with real (if secondary) diversification beyond Fort Campbell -- the only real drags are modest rent growth and a thin, less-tracked exit market.', 'Call 2 local PM firms and 1 broker to confirm actual portfolio vacancy and buyer depth before committing.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('002d7a44-6b4b-4cb9-b69f-701e12c32f65', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Miami-Dade', 'Miami-Dade, FL', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Rent-to-income near 48% and insurance running 1.5-2.5% of value annually are both punitive by any standard, despite genuinely strong population, jobs, and liquidity.', 'Pass for buy-and-hold at typical price points; would need a very specific value-add or workforce-housing angle to make the math work.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('df36990d-b876-4a14-8f15-2c75073e8626', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Fort Myers', 'Fort Myers, FL', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Negative rent growth and the most expensive insurance environment researched (up to $8K+/yr) stack against otherwise decent population and job growth.', 'Get 2 actual landlord-insurance quotes before underwriting anything here -- the insurance line alone could decide this market.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('f0af805b-9177-42db-8fab-7e90f57ba655', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Dallas-Fort Worth', 'Dallas-Fort Worth, TX', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'Best-in-class population growth (#1 in the US) and a huge diverse economy are currently offset by three operator-layer reds (rent growth, vacancy, supply) from a historic construction wave still working through the system.', 'Revisit once Q2/Q3 2026 data confirms the forecast ~30bps vacancy improvement -- the demand case is real, the timing isn''t yet.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('1dd67060-9a9a-4e7e-a8b5-d0272b0fa397', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Austin', 'Austin, TX', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'Strongest job growth and income cushion researched, but severe current oversupply (13.5% vacancy, rents down up to 4.7%) makes this a timing story, not a today story.', 'Watch for the forecast vacancy improvement (13.5% to ~11%) to show up in Q2/Q3 2026 prints before committing capital.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('5a6a845a-a023-40ca-a410-4e0b07570e89', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Atlanta', 'Atlanta, GA', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'go', 'Rent growth has already reversed to a forecast +4.1% for 2026, vacancy is improving, and this is one of the most actively traded multifamily markets in the country right now -- greens clearly outnumber the single red (trailing rent growth, which has already turned).', 'Start broker outreach; factor GA HB399''s out-of-state PM/broker requirement into your first calls.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('5b14e05d-40dc-4265-b39c-5d77e78c6fad', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Raleigh', 'Raleigh, NC', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'Strong Foundation and an improving supply picture, but rent growth is essentially flat and liquidity data couldn''t be confirmed as strongly as Atlanta or Charlotte.', 'Call 2 PM firms for real rent-growth trajectory as the 2025 supply wave clears.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('afe33203-1d38-4e61-92b1-44cd312b0ffe', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Richmond', 'Richmond, VA', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'A genuinely strong operator layer (rent growth, vacancy, liquidity all green, with multiple reports calling this a buying opportunity) is held back by softer Foundation numbers -- job growth, income and landlord law are all a notch below the stronger markets on this list.', 'Worth a second look once VA''s 2026 tenant-protection rollout settles and you''ve confirmed actual rents against the newer, higher figures.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('9f3968fa-783b-424c-954d-03797c28aa3e', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Jacksonville', 'Jacksonville, FL', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Rent growth, vacancy, supply and taxes/insurance are all red at the same time, and they''re compounding each other -- oversupply is driving both the rent decline and the vacancy, with insurance as the wildcard on top.', 'Re-check absorption vs. deliveries and get 2 actual landlord-insurance quotes before underwriting; if rent growth and vacancy haven''t turned, move on.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('8252c196-2f36-4e84-9cb1-2c6122e9caff', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Nashville', 'Nashville, TN', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'go', 'The strongest sheet of the entire batch -- reaccelerating rent growth, improving supply-demand balance, and a genuinely diversified economy, with only two rows (crime data quality, general access) unresolved.', 'Verify the rent-growth discrepancy (an older -4.0% figure vs. a fresh +3.4% report) with a broker call, then start outreach.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('a3b2b2a9-71b2-4986-a6a8-87c513621fc0', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Houston', 'Houston, TX', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'A huge, diversified economy and a fast-clearing supply pipeline are offset by flat rents, elevated vacancy, and the only crime red among the stronger markets researched.', 'Verify the specific submarket''s crime profile (this is very submarket-dependent in Houston) before narrowing in.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('d8e04602-28a4-4af0-82d0-8124592b56cc', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Charlotte', 'Charlotte, NC', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', '11 straight quarters of rent declines is a real headwind, but vacancy is healthy, the pipeline is balancing, and this is one of the most actively traded markets researched -- banking-sector concentration is the other flag worth naming.', 'Confirm rent comps are stabilizing (forecast to turn positive in 2027) before underwriting a rent-growth thesis.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('290ffcf0-822e-4164-93ab-9faae3c260a2', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Broward', 'Broward, FL', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Despite the highest median income researched, rent-to-income and insurance costs are both stretched to punitive -- the same fundamental affordability problem as Miami-Dade, just slightly less severe.', 'Pass for typical buy-and-hold economics; the international-capital liquidity story is real but doesn''t fix the operating cost structure.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('ffd2d451-93f4-4f15-96f0-f7c8f19e7f31', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Killeen', 'Killeen, TX', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Fort Cavazos dependency (a core red) plus worsening vacancy (8.0% to 9.7%) are the central issues on an otherwise workable, low-crime, landlord-friendly market.', 'Name this for what it is -- a single-installation market -- and only proceed if comfortable underwriting that risk explicitly.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('d6ea1b88-1211-4f42-a517-57ceb43aeb50', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Winston-Salem', 'Winston-Salem, NC', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Weak population and job growth, borderline-high crime, and the thinnest PM/liquidity picture of the NC markets researched make this the weakest of that group, though nothing here is a core red.', 'Revisit if the BioNest life-sciences investment materially changes the job-growth picture; not a priority market today.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('8571dcfe-8c4c-46a9-84aa-355deebda1d9', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Norfolk', 'Norfolk, VA', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Strong, consistent rent growth and tight vacancy are real positives, but near-flat population growth and Naval Station Norfolk dependency (both core reds) are the same category of risk the SOP-style framework is built to catch.', 'Name the military-dependency risk explicitly if proceeding; otherwise this is a pass on the Foundation layer alone.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('d2a7a0b1-e75b-4812-81f0-2a4356fd7e88', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Lexington', 'Lexington, KY', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'watch', 'The strongest rent growth of the entire list (+5.0%) and a more diversified employer base than expected are genuinely exciting, but population and job growth are both soft.', 'This is the one ''second look'' market worth a broker call to sanity-check the rent-growth number and confirm underlying demand isn''t just a Toyota-expansion blip.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z'),
  ('93cbb027-d9f7-441f-bc01-7cc24e40d1c4', 'a8938ed0-9c4e-4d42-b874-593b4b3c90a9', 'Memphis', 'Memphis, TN', 'buy_and_hold', '10-20 unit value-add BRRRR. Seeded from Alexander Celestina''s Market Analysis workbook (Aug 2026).', 'multifamily', 'no_go', 'Stagnant population, the weakest job growth researched, the worst crime score researched, and one of the highest property tax burdens researched all stack together -- three separate core reds (population, job growth, and the resulting strategy-fit red).', 'Pass. Don''t reopen without 90 days of genuinely new information -- a real change in the job-growth trend, not just cheap pricing.', '2026-08-19T19:21:13Z', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z', '2026-08-19T19:21:13Z');insert into public.market_scorecard_rows (market_id, category, rating, note, is_core_red, updated_by_kind, updated_by, updated_at) values
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'population_trend', 'green', '5-yr trend growing ~1.5%/yr, above the 1.25% local target.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'job_growth', 'green', 'Payrolls growing ~2.2%/yr, above the 2.0% target; unemployment 2.9%, well under state and national rates.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'major_employers', 'green', 'UT-Knoxville, Covenant Health, TVA, DENSO, Regal Rexnord, plus Oak Ridge National Lab nearby -- diverse base.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'median_household_income', 'yellow', 'MHI ~$57.3K vs. ~$1,470 asking rent = ~30.8% of income -- tight but workable, not comfortable.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'rent_growth_trend', 'yellow', 'Fresh Q1 2026 data shows asking rents down 0.9% YoY (median rent down 3.3%), contradicting an older data point of +3.5% -- treating the more recent, specific report as authoritative: flat/choppy, not stable.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'vacancy_trend', 'green', 'Occupancy running 94.9-97% (some of the tightest submarkets in TN) -- vacancy roughly 3-5%, healthy.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'supply_pipeline', 'yellow', '4,657 units underway is a robust pipeline for a metro this size -- noticeable, but a $114M stadium project and a $300M business park are adding jobs alongside the units, which helps absorption.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'affordability_for_tenant', 'yellow', 'Same ~30.8% rent-to-income -- slightly stretched for the target tenant.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'crime_neighborhood', 'yellow', 'Crime index 459.4, close to the 500-point ceiling -- borderline for a standard buy box.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'school_retail_access', 'yellow', 'Varies by submarket -- confirm at the asset level.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'property_management_depth', 'green', 'Reasonable PM bench assumed for a metro this size -- verify with 2 calls.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'landlord_friendliness', 'green', 'TN favors landlords -- no rent control, 35-50 day eviction.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'taxes_insurance', 'yellow', 'Property tax is low (~0.49% statewide), but landlord insurance premiums are up ~22% over two years across TN -- a volatility flag.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'liquidity_exit', 'yellow', '$196M in 2025 multifamily sales with price-per-unit down 6.2% -- some activity, but softening pricing signals moderate, not deep, liquidity.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'deal_size_fit', 'green', '10-20 unit stock is available in a market this size.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f8498b86-a56f-4820-aab5-4d90d3dd4acc', 'strategy_fit', 'yellow', 'Tight rents and softening per-unit pricing cut both ways -- workable but not a clean fit right now.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'population_trend', 'green', 'Population growing ~2.3%/yr, the fastest of the group researched.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'job_growth', 'green', 'Payrolls growing ~3.4%/yr, outpacing every other market.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'major_employers', 'yellow', 'Redstone Arsenal and its contractor base (NASA, Army, Missile Defense Agency, Boeing, Lockheed, Northrop, Blue Origin) dominate the economy -- many employers, but one federal-budget-exposed cluster.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'median_household_income', 'green', 'MHI ~$83.2K vs. ~$1,525 rent = ~22% of income -- the most comfortable margin researched.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'rent_growth_trend', 'green', 'Rents up 2.2-3.8% depending on source -- stable to positive, the strongest of the group.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'vacancy_trend', 'green', 'Vacancy ~5.5% -- healthy and stable.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
  ('f0d75fd2-8355-46ff-82ed-b105070267cf', 'supply_pipeline', 'yellow', '6,300 units delivered in the past year after 16,000+ over three years; developers pulling back into 2026 but the pipeline hasn''t fully cleared.', false, 'human', '07d7e929-345e-4b1f-a681-6191739169b7', '2026-08-19T19:21:13Z'),
